const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async()=>{const browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});const page=await browser.newPage({viewport:{width:1280,height:800}});let errs=[];page.on('pageerror',e=>errs.push(e.message));await page.goto('http://localhost:3002');await page.waitForTimeout(500);await page.locator('#startBtn').click();await page.waitForTimeout(1600);await page.keyboard.press('ArrowLeft');await page.waitForTimeout(300);await page.screenshot({path:'/tmp/opencode/metro-check.jpg',type:'jpeg',quality:80});console.log(JSON.stringify({title:await page.title(),distance:await page.locator('#distance').textContent(),mode:await page.locator('#startScreen').getAttribute('class'),errors:errs}));await browser.close()})().catch(e=>{console.error(e);process.exit(1)});
